namespace huffman {

class Node {
public:
    unsigned char character;
    int frequency;
    std::shared_ptr<Node> left;
    std::shared_ptr<Node> right;

    Node(unsigned char ch, int freq) : character(ch), frequency(freq), left(nullptr), right(nullptr) {}
};

std::string decode_data(std::ifstream &infile, std::shared_ptr<Node> &root, int encoded_length) {
    std::string decoded_text;
    decoded_text.reserve(encoded_length);

    unsigned char current_byte;
    int bit_in_byte = 0;
    std::shared_ptr<Node> current = root;

    for (int i = 0; i < encoded_length; i++) {
        // Read a new byte when needed
        if (bit_in_byte == 0) {
            infile.read(reinterpret_cast<char*>(&current_byte), 1);
            if (infile.gcount() == 0) {
                break;  // End of file
            }
        }

        // Extract bit from MSB side (matching the encoding order)
        int bit = (current_byte >> (7 - bit_in_byte)) & 1;

        // Move to left or right child based on bit
        if (bit == 0) {
            current = current->left;
        } else {
            current = current->right;
        }

        // If we reached a leaf node, add character to result and restart from root
        if (current->left == nullptr && current->right == nullptr) {
            decoded_text += current->character;
            current = root;
        }

        // Move to next bit in byte
        bit_in_byte = (bit_in_byte + 1) % 8;
    }

    return decoded_text;
}

} // namespace huffman

